### Steps to reproduce

1. Run the attached sample on an Android device with WebView version 157
2. Tap Start
3. The code navigates to a new page in the WebView and runs Javascript during the navigation.

### Expected results

All Javascript executions should complete their future and return a result.

### Actual results

An awaited `runJavaScriptReturningResult("1 + 1")` Future remains pending forever, even after the replacement document finishes loading. No result or error arrives.
The error can also be reproduced with `runJavaScript`.

### Suspected cause
[Chromium change 8470690](https://chromium-review.googlesource.com/c/chromium/src/+/8470690), merged September 30, 2026, removes a restriction that prevented same-site `RenderFrameHost` replacement when the initial page scale is non-default.

The [Android plugin enables `setLoadWithOverviewMode(true)` by default](https://github.com/flutter/packages/blob/main/packages/webview_flutter/webview_flutter_android/lib/src/android_webview_controller.dart) (i.e. non-default initial page scale as described in the chromium change). The WebViews used to be on the exemption path in Chromium 156; that exemption is removed in 157.

I tested disabling the WebViewRenderDocument feature flag in the WebView DevTools and then the issue can no longer be reproduced.

### Code sample

<details open><summary>Code sample</summary>

```dart
import "dart:async";
import "dart:io";

import "package:flutter/material.dart";
import "package:webview_flutter/webview_flutter.dart";

void main() => runApp(const MaterialApp(home: ReproPage()));

class ReproPage extends StatefulWidget {
  const ReproPage({super.key});

  @override
  State<ReproPage> createState() => _ReproPageState();
}

class _ReproPageState extends State<ReproPage> {
  final _webViewController = WebViewController();
  final _javaScriptStopwatch = Stopwatch();
  HttpServer? _httpServer;
  Timer? _statusUpdateTimer;
  Completer<void> _pageLoadCompleter = Completer<void>();
  String _statusMessage = "Tap Start to test.";

  Future<void> _runTest() async {
    setState(() => _statusMessage = "Running…");
    final httpServer = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    _httpServer = httpServer;
    httpServer.listen((httpRequest) async {
      // Allow JS execution in the outgoing document before navigation commits.
      await Future<void>.delayed(const Duration(milliseconds: 50));
      httpRequest.response.headers.contentType = ContentType.html;
      httpRequest.response.write("<h1>${httpRequest.uri.path}</h1>");
      await httpRequest.response.close();
    });
    await _webViewController.setJavaScriptMode(JavaScriptMode.unrestricted);
    await _webViewController.setNavigationDelegate(
      NavigationDelegate(onPageFinished: (_) => _pageLoadCompleter.complete()),
    );
    int javaScriptCallCount = 0;
    // Observation only: this timer does not complete or cancel the awaited Future.
    _statusUpdateTimer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (_javaScriptStopwatch.isRunning &&
          _javaScriptStopwatch.elapsed.inSeconds >= 3 &&
          _pageLoadCompleter.isCompleted) {
        setState(
          () => _statusMessage =
              "Page loaded. JavaScript call #$javaScriptCallCount still pending (${_javaScriptStopwatch.elapsed.inSeconds}s).",
        );
      }
    });
    for (int pageIndex = 0; pageIndex < 24 && mounted; pageIndex++) {
      _pageLoadCompleter = Completer<void>();
      await _webViewController.loadRequest(Uri.parse("http://127.0.0.1:${httpServer.port}/page-$pageIndex"));
      // Fully load the first page before testing JS execution during subsequent page loads.
      if (pageIndex == 0) await _pageLoadCompleter.future;
      while (mounted && !_pageLoadCompleter.isCompleted) {
        javaScriptCallCount++;
        debugPrint("JavaScript call #$javaScriptCallCount started");
        _javaScriptStopwatch.reset();
        _javaScriptStopwatch.start();
        await _webViewController.runJavaScriptReturningResult("1 + 1");
        _javaScriptStopwatch.stop();
        debugPrint("JavaScript call #$javaScriptCallCount completed");
      }
    }
    if (mounted) setState(() => _statusMessage = "No hang observed. Restart the app to retry.");
  }

  @override
  void dispose() {
    _statusUpdateTimer?.cancel();
    unawaited(_httpServer?.close(force: true));
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text("JavaScript navigation test")),
    body: Column(
      children: [
        FilledButton(
          onPressed: _httpServer == null && _statusMessage == "Tap Start to test." ? _runTest : null,
          child: const Text("Start"),
        ),
        Padding(padding: const EdgeInsets.all(16), child: Text(_statusMessage)),
        Expanded(child: WebViewWidget(controller: _webViewController)),
      ],
    ),
  );
}
