// Minimal repro: toByteData readbacks and image draws with Impeller (Metal)
// on a discrete GPU. No third-party code, no custom fonts.
import 'dart:async';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

const int kSize = 64;

Uint8List orangePixels() {
  final p = Uint8List(kSize * kSize * 4);
  for (var i = 0; i < p.length; i += 4) {
    p[i] = 255; p[i + 1] = 128; p[i + 2] = 0; p[i + 3] = 255;
  }
  return p;
}

ui.Picture orangePicture() {
  final rec = ui.PictureRecorder();
  final c = ui.Canvas(rec);
  c.drawRect(const ui.Rect.fromLTWH(0, 0, 64, 64),
      ui.Paint()..color = const ui.Color.fromARGB(255, 255, 128, 0));
  return rec.endRecording();
}

Future<ui.Image> viaDecodeImageFromPixels() {
  final c = Completer<ui.Image>();
  ui.decodeImageFromPixels(orangePixels(), kSize, kSize,
      ui.PixelFormat.rgba8888, c.complete);
  return c.future;
}

Future<ui.Image> viaImageDescriptorRaw() async {
  final buf = await ui.ImmutableBuffer.fromUint8List(orangePixels());
  final d = ui.ImageDescriptor.raw(buf,
      width: kSize, height: kSize, pixelFormat: ui.PixelFormat.rgba8888);
  final codec = await d.instantiateCodec();
  return (await codec.getNextFrame()).image;
}

Future<ui.Image> viaPictureToImage() => orangePicture().toImage(kSize, kSize);
Future<ui.Image> viaPictureToImageSync() async =>
    orangePicture().toImageSync(kSize, kSize);

class Result {
  Result(this.name, this.image, this.summary);
  final String name;
  final ui.Image image;
  final String summary;
}

Future<String> readBack(ui.Image img) async {
  final bd = await img.toByteData(format: ui.ImageByteFormat.rawRgba);
  if (bd == null) return 'toByteData returned null';
  final b = bd.buffer.asUint8List();
  var nonZero = 0;
  for (final v in b) { if (v != 0) nonZero++; }
  final mid = ((kSize ~/ 2) * kSize + kSize ~/ 2) * 4;
  return 'first px ${b[0]},${b[1]},${b[2]},${b[3]}  '
      'centre px ${b[mid]},${b[mid + 1]},${b[mid + 2]},${b[mid + 3]}  '
      'non-zero bytes $nonZero of ${b.length}';
}

void main() => runApp(const ReproApp());

class ReproApp extends StatefulWidget {
  const ReproApp({super.key});
  @override
  State<ReproApp> createState() => _ReproAppState();
}

class _ReproAppState extends State<ReproApp> {
  final List<Result> results = [];

  @override
  void initState() {
    super.initState();
    _run();
  }

  Future<void> _run() async {
    final makers = <String, Future<ui.Image> Function()>{
      'decodeImageFromPixels': viaDecodeImageFromPixels,
      'ImageDescriptor.raw': viaImageDescriptorRaw,
      'Picture.toImage': viaPictureToImage,
      'Picture.toImageSync': viaPictureToImageSync,
    };
    for (final e in makers.entries) {
      final img = await e.value();
      final s = await readBack(img);
      // ignore: avoid_print
      print('READBACK ${e.key}: $s');
      setState(() => results.add(Result(e.key, img, s)));
    }
    // ignore: avoid_print
    print('READBACK done');
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: Scaffold(
        backgroundColor: const Color(0xFF808080),
        body: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Expected: four orange squares; readback 255,128,0,255',
                  style: TextStyle(fontSize: 16, color: Colors.white)),
              const SizedBox(height: 8),
              Row(children: [
                Container(width: 64, height: 64, color: const Color(0xFFFF8000)),
                const SizedBox(width: 8),
                const Text('<- plain Container (control)',
                    style: TextStyle(color: Colors.white)),
              ]),
              const SizedBox(height: 12),
              for (final r in results)
                Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: Row(children: [
                    RawImage(image: r.image, width: 64, height: 64),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text('${r.name}\n${r.summary}',
                          style: const TextStyle(
                              color: Colors.white, fontSize: 13)),
                    ),
                  ]),
                ),
            ],
          ),
        ),
      ),
    );
  }
}
