#import <Metal/Metal.h>
#include <stdio.h>
static NSArray<id<MTLDevice>> *rad_copy_all(void) __attribute__((ns_returns_retained));
static NSArray<id<MTLDevice>> *rad_copy_all(void) {
  NSArray<id<MTLDevice>> *all = MTLCopyAllDevices();
  NSMutableArray *out = [NSMutableArray array];
  for (id<MTLDevice> d in all) if (!d.hasUnifiedMemory) [out addObject:d];
  fprintf(stderr, "only_discrete: MTLCopyAllDevices -> %lu of %lu devices (%s)\n",
          (unsigned long)out.count, (unsigned long)all.count,
          out.count ? [[(id<MTLDevice>)out[0] name] UTF8String] : "none");
  return out.count ? out : all;
}
