```dart
import 'dart:async';
import 'dart:convert';
import 'dart:developer';

import 'package:flutter/material.dart';
import 'package:flutter/semantics.dart';

void main() => runApp(const MaterialApp(home: Repro()));

class Repro extends StatefulWidget {
  const Repro({super.key});

  @override
  State<Repro> createState() => _ReproState();
}

class _ReproState extends State<Repro> {
  // Keep semantics active without requiring a screen reader in the test setup.
  late final SemanticsHandle _semantics;
  int _step = 0;
  int _page = 3;
  bool _running = false;
  bool _stepping = false;
  static const _includePage = bool.fromEnvironment(
    'INCLUDE_PAGE_SEMANTICS',
    defaultValue: true,
  );

  @override
  void initState() {
    super.initState();
    _semantics = SemanticsBinding.instance.ensureSemantics();
    // Allows an external sampler to advance one rendered frame at a time.
    registerExtension('ext.repro.step', (method, parameters) async {
      if (_running || _stepping) {
        return ServiceExtensionResponse.error(-32000, 'Already running');
      }
      await _advance();
      return ServiceExtensionResponse.result(jsonEncode({'step': _step}));
    });
    registerExtension('ext.repro.status', (method, parameters) async {
      return ServiceExtensionResponse.result(jsonEncode({
        'step': _step,
        'page': _page,
        'semanticsEnabled': SemanticsBinding.instance.semanticsEnabled,
        'includePageSemantics': _includePage,
      }));
    });
  }

  Future<void> _advance() async {
    _stepping = true;
    setState(() {
      _page += _step % 6 < 3 ? -1 : 1;
      _step++;
    });
    await WidgetsBinding.instance.endOfFrame;
    // Let the platform thread process the resulting semantics update.
    await Future<void>.delayed(const Duration(milliseconds: 100));
    _stepping = false;
  }

  Future<void> _run() async {
    if (_running || _stepping) return;
    setState(() => _running = true);
    for (var i = 0; i < 1200 && mounted; i++) {
      await _advance();
    }
    if (mounted) setState(() => _running = false);
  }

  @override
  void dispose() {
    _semantics.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Accessibility retention: step $_step')),
      body: Column(
        children: [
          Row(children: [
            TextButton(
              onPressed: _running || _stepping ? null : _advance,
              child: const Text('One navigation step'),
            ),
            TextButton(
              onPressed: _running || _stepping ? null : _run,
              child: const Text('Run 1200 steps'),
            ),
          ]),
          ExcludeSemantics(
            excluding: !_includePage,
            child: KeyedSubtree(
              key: ValueKey(_page),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: List.generate(
                  32,
                  (line) => Text(
                    'Page $_page, line $line: a short generated passage.',
                    style: const TextStyle(fontSize: 12, height: 1.2),
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}
