    parser.add_argument('out', type=Path)
    parser.add_argument('--steps', type=int, default=1200)
    parser.add_argument('--heaptrack', type=Path)
    parser.add_argument('--preload', type=Path,
                        help='Optional diagnostic native library; separate from baseline runs')
    parser.add_argument('--display', type=int, default=97)
    parser.add_argument('--idle', type=int, default=15)
    args = parser.parse_args()
    args.out.mkdir(parents=True, exist_ok=False)
    args.out = args.out.resolve()
    binary = args.bundle.resolve() / 'semantics_retention'
    if not binary.is_file():
        parser.error(f'Bundle executable missing: {binary}')
    display_socket = Path(f'/tmp/.X11-unix/X{args.display}')
    if display_socket.exists():
        parser.error(f'Display :{args.display} already exists; choose another')
    with socket.socket() as sock:
        sock.bind(('127.0.0.1', 0))
        port = sock.getsockname()[1]
    vm = f'http://127.0.0.1:{port}/'

    def rpc(method, **params):
        query = urllib.parse.urlencode(params)
        url = vm + method + ('?' + query if query else '')
        with urllib.request.urlopen(url, timeout=30) as response:
            data = json.load(response)
        if 'error' in data:
            raise RuntimeError(data['error'])
        return data['result']

    display = None
    app = None
    pid = None
    try:
        with (args.out / 'xvfb.log').open('w') as log:
            display = subprocess.Popen(
                ['Xvfb', f':{args.display}', '-screen', '0', '1366x768x24'],
                stdout=log, stderr=subprocess.STDOUT,
            )
        deadline = time.monotonic() + 15
        while not display_socket.exists():
            if display.poll() is not None or time.monotonic() > deadline:
                raise RuntimeError('Xvfb did not start')
            time.sleep(0.05)
        env = os.environ.copy()
        env.update({
            'DISPLAY': f':{args.display}',
            'FLUTTER_ENGINE_SWITCHES': '2',
            'FLUTTER_ENGINE_SWITCH_1': f'vm-service-port={port}',
            'FLUTTER_ENGINE_SWITCH_2': 'disable-service-auth-codes',
        })
        if args.preload:
            env['LD_PRELOAD'] = str(args.preload.resolve()) + (
                ':' + env['LD_PRELOAD'] if env.get('LD_PRELOAD') else '')
        for kind in ('data', 'config', 'cache'):
            path = args.out / f'xdg-{kind}'
            path.mkdir()
            env[f'XDG_{kind.upper()}_HOME'] = str(path)
        command = [str(binary)]
        if args.heaptrack:
            command = [str(args.heaptrack.resolve()), '--record-only', '-o',
                       str(args.out / 'heaptrack')] + command
        with (args.out / 'app.log').open('w') as log:
            app = subprocess.Popen(command, env=env, stdout=log,
                                   stderr=subprocess.STDOUT, start_new_session=True)
        deadline = time.monotonic() + 60
        while True:
            try:
                info = rpc('getVM')
                pid = info['pid']
                isolate = info['isolates'][0]['id']
                status = rpc('ext.repro.status', isolateId=isolate)
                break
            except Exception:
                if app.poll() is not None or time.monotonic() > deadline:
                    raise RuntimeError('App / VM service did not start')
                time.sleep(0.2)
        print('START', json.dumps({'pid': pid, 'status': status}), flush=True)
        time.sleep(3)

        def proc():
            values = {}
            for line in Path(f'/proc/{pid}/status').read_text().splitlines():
                key, _, value = line.partition(':')
                if key in ('VmRSS', 'RssAnon', 'RssFile', 'VmHWM'):
                    values[key] = int(value.split()[0])
            return values

        def checkpoint(step, label='navigation'):
            record = {'step': step, 'label': label, 'time': time.time(),
                      'proc_before_gc_kib': proc(),
                      'memory_before_gc': rpc('getMemoryUsage', isolateId=isolate)}
            allocation = rpc('getAllocationProfile', isolateId=isolate, gc='true')
            record['memory_after_gc'] = allocation['memoryUsage']
            record['classes'] = allocation['members']
            time.sleep(1)
            record['proc_after_gc_kib'] = proc()
            record['status'] = rpc('ext.repro.status', isolateId=isolate)
            if args.preload:
                matches = re.findall(r'\[node-counter\] created=(\d+) freed=(\d+)',
                                     (args.out / 'app.log').read_text())
                record['native_counter'] = dict(zip(('created', 'finalized'),
                                                     map(int, matches[-1]))) if matches else None
            with (args.out / 'checkpoints.jsonl').open('a') as out:
                out.write(json.dumps(record) + '\n')
            print('CHECKPOINT', step, label,
                  'RssAnon_after_GC_MiB=%.3f' %
                  (record['proc_after_gc_kib']['RssAnon'] / 1024),
                  'Dart_heap_after_GC_MiB=%.3f' %
                  (record['memory_after_gc']['heapUsage'] / 2**20), flush=True)

        checkpoint(0)
        for step in range(1, args.steps + 1):
            result = rpc('ext.repro.step', isolateId=isolate)
            if result['step'] != step:
                raise RuntimeError(f'Unexpected step response: {result}')
            if step % 120 == 0:
                checkpoint(step)
        if args.steps % 120:
            checkpoint(args.steps)
        time.sleep(args.idle)
        checkpoint(args.steps, 'after_idle')
        # Linux SIGTERM deliberately ends recording with the view still live.
        # Heaptrack's outstanding allocations then describe retention during
        # the view lifetime, not proof of a leak after normal view disposal.
        os.kill(pid, signal.SIGTERM)
        app.wait(timeout=30)
        print('DONE', args.out, flush=True)
    finally:
        if app is not None and app.poll() is None:
            os.killpg(app.pid, signal.SIGTERM)
            try:
                app.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(app.pid, signal.SIGKILL)
                app.wait(timeout=10)
        if display is not None and display.poll() is None:
            display.terminate()
            display.wait(timeout=10)


if __name__ == '__main__':
    main()
```

