import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/painting.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

// Two identical Hebrew lines. The first is terminated by a hard line break,
// the second is the last line of the paragraph. Both should measure the same.
const String line = 'שלום עולם טוב';

Future<(int, int)> inkExtent(
  TextPainter painter,
  double top,
  double bottom,
) async {
  final recorder = ui.PictureRecorder();
  final canvas = Canvas(recorder);
  canvas.drawColor(const Color(0xFFFFFFFF), BlendMode.src);
  painter.paint(canvas, Offset.zero);
  final image = await recorder.endRecording().toImage(
    painter.width.ceil(),
    painter.height.ceil(),
  );
  final data = (await image.toByteData())!;
  var minX = image.width, maxX = -1;
  for (var y = top.ceil(); y < bottom.floor(); y++) {
    for (var x = 0; x < image.width; x++) {
      if (data.getUint8((y * image.width + x) * 4) < 128) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
      }
    }
  }
  return (minX, maxX + 1);
}

