    Platform.environment['REPRO_FONT'] ?? 'C:/Windows/Fonts/arial.ttf';

void main() {
  setUpAll(() async {
    final bytes = File(fontPath).readAsBytesSync();
    await (FontLoader(
      'ReproFont',
    )..addFont(Future.value(ByteData.sublistView(bytes)))).load();
  });
  for (final separator in ['\n', '\u2028', '\u2029']) {
    final name =
        'U+${separator.codeUnitAt(0).toRadixString(16).padLeft(4, '0')}';
    testWidgets('RTL line ending with $name', (tester) async {
      final painter = TextPainter(
        text: TextSpan(
          text: '$line$separator$line',
          style: const TextStyle(
            fontFamily: 'ReproFont',
            fontSize: 20,
            color: Color(0xFF000000),
          ),
        ),
        textDirection: TextDirection.rtl,
      )..layout(minWidth: 400, maxWidth: 400);

      const n = line.length;
      const secondStart = n + 1;
      TextBox box(int offset) => painter
          .getBoxesForSelection(
            TextSelection(baseOffset: offset, extentOffset: offset + 1),
          )
          .single;

      final firstLine = painter.getBoxesForSelection(
        const TextSelection(baseOffset: 0, extentOffset: n),
      );
      final secondLine = painter.getBoxesForSelection(
        const TextSelection(
          baseOffset: secondStart,
          extentOffset: secondStart + n,
        ),
      );
      final breakBox = painter.getBoxesForSelection(
        const TextSelection(baseOffset: n, extentOffset: n + 1),
      );
      final lines = painter.computeLineMetrics();
      final (ink1Left, ink1Right) = (await tester.runAsync(
        () => inkExtent(painter, 0, lines[0].height),
      ))!;
      final (ink2Left, ink2Right) = (await tester.runAsync(
        () => inkExtent(
          painter,
          lines[0].height,
          lines[0].height + lines[1].height,
        ),
      ))!;

      // Hit-test the painted center of the first character of line 2, at line 1's y.
      final probeX = box(secondStart).toRect().center.dx;
      final hit = painter.getPositionForOffset(
        Offset(probeX, lines[0].baseline - 2),
      );

      // ignore: avoid_print
      print(
        '''
$name
  line 1 (ends with $name) boxes : ${firstLine.map((b) => '[${b.left.toStringAsFixed(2)}, ${b.right.toStringAsFixed(2)}]').join(' ')}
  line 2 (last line)       boxes : ${secondLine.map((b) => '[${b.left.toStringAsFixed(2)}, ${b.right.toStringAsFixed(2)}]').join(' ')}
  hard break box                 : ${breakBox.map((b) => '[${b.left.toStringAsFixed(2)}, ${b.right.toStringAsFixed(2)}]').join(' ')}
  first char box  line1 / line2  : [${box(0).left}, ${box(0).right}] / [${box(secondStart).left}, ${box(secondStart).right}]
  painted ink x   line1 / line2  : [$ink1Left, $ink1Right) / [$ink2Left, $ink2Right)
  getPositionForOffset at painted center of first char, line 1: ${hit.offset} (expected 0)''',
      );

      expect(ink1Left, ink2Left, reason: 'glyphs paint at the same x');
      expect(
        box(0).left,
        box(secondStart).left,
        reason: 'boxes should match the painted glyphs',
      );
      expect(hit.offset, 0);
