import 'dart:math' as math;

import 'package:flutter/material.dart';

// Synthetic rendering probe. No network, plugins, accounts, or stored data.
void main() => runApp(const MaterialApp(home: RenderProbe()));

class RenderProbe extends StatefulWidget {
  const RenderProbe({super.key});
  @override
  State<RenderProbe> createState() => _RenderProbeState();
}

class _RenderProbeState extends State<RenderProbe>
    with SingleTickerProviderStateMixin {
  final clock = Stopwatch()..start();
  late final AnimationController ticker;
  int lastPage = -2;
  int pageOffset = 0;

  @override
  void initState() {
    super.initState();
    ticker =
        AnimationController(vsync: this, duration: const Duration(seconds: 2))
          ..addListener(() => setState(() {}))
          ..repeat();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      debugPrint('RENDER_PROBE first framework frame completed');
    });
  }

  @override
  void dispose() {
    ticker.dispose();
    clock.stop();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final seconds = clock.elapsedMilliseconds / 1000.0;
    final page = seconds < 2 ? -1 : (((seconds - 2) ~/ 3) + pageOffset) % 2;
    if (page != lastPage) {
      debugPrint(
        'RENDER_PROBE page=$page elapsed=${seconds.toStringAsFixed(1)}s',
      );
      lastPage = page;
    }
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: () => setState(() => pageOffset++),
      child: CustomPaint(
        painter: ProbePainter(page, ticker.value),
        size: Size.infinite,
      ),
    );
  }
}

class ProbePainter extends CustomPainter {
  ProbePainter(this.page, this.phase);
  final int page;
  final double phase;

  void label(
    Canvas canvas,
    String text,
    Offset position,
    double size,
    Color color,
