    final painter = TextPainter(
      text: TextSpan(
        text: text,
        style: TextStyle(
          fontFamily: 'ProbeRoboto',
          fontSize: size,
          color: color,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout(maxWidth: 900);
    painter.paint(canvas, position);
    painter.dispose();
  }

  @override
  void paint(Canvas canvas, Size size) {
    // Fixed logical coordinates keep screenshots comparable on any panel size.
    canvas.scale(size.width / 1000, size.height / 700);
    canvas.drawColor(
      page < 0 ? Colors.white : const Color(0xff102030),
      BlendMode.src,
    );
    if (page < 0) {
      canvas.drawRect(
        const Rect.fromLTWH(40, 40, 920, 80),
        Paint()..color = Colors.red,
      );
      canvas.drawRect(
        const Rect.fromLTWH(40, 580, 920, 80),
        Paint()..color = Colors.green,
      );
      label(canvas, 'START', const Offset(60, 230), 150, Colors.black);
      return;
    }
    label(canvas, 'PAGE ${page + 1}', const Offset(40, 30), 64, Colors.white);
    label(
      canvas,
      'Auto switch: 3 s / tap to switch',
      const Offset(40, 110),
      28,
      Colors.white,
    );
    final moving = 40 + phase * 800;
    canvas.drawRect(
      Rect.fromLTWH(moving, 160, 120, 20),
      Paint()..color = Colors.lime,
