  final Map<int, List<int>> nodes = <int, List<int>>{};
  final List<String> problems = <String>[];

  @override
  ui.SemanticsUpdateBuilder createSemanticsUpdateBuilder() => _Builder(this);

  void check() {
    final parents = <int, int>{};
    void visit(int id) {
      for (final int child in nodes[id] ?? const <int>[]) {
        if (parents.containsKey(child)) {
          problems.add('$child listed under ${parents[child]} and $id');
          continue;
        }
        parents[child] = id;
        visit(child);
      }
    }

    visit(0);
  }
}

class _Builder implements ui.SemanticsUpdateBuilder {
  _Builder(this.binding);
  final _Binding binding;
  final ui.SemanticsUpdateBuilder _delegate = ui.SemanticsUpdateBuilder();

  @override
  dynamic noSuchMethod(Invocation invocation) {
    switch (invocation.memberName) {
      case #updateNode:
        binding.nodes[invocation.namedArguments[#id] as int] = List<int>.from(
          invocation.namedArguments[#childrenInTraversalOrder] as Iterable<dynamic>,
        );
        return Function.apply(
          _delegate.updateNode,
          invocation.positionalArguments,
          invocation.namedArguments,
        );
      case #build:
        binding.check();
        return _delegate.build();
      default:
        return Function.apply(
          _delegate.updateCustomAction,
          invocation.positionalArguments,
          invocation.namedArguments,
        );
    }
  }
}

