import 'dart:async';

import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

void log(String message) => print('REPRO $message');

/// Starts [call] and logs when it completes; reports it as pending after 5 s.
void probe(String name, Future<Object?> Function() call) {
  var done = false;
  call().then(
    (value) => log('$name completed: $value'),
    onError: (Object e) => log('$name failed: $e'),
  ).whenComplete(() => done = true);
  Timer(const Duration(seconds: 5), () {
    if (!done) log('$name still pending after 5 s');
  });
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  log('main started');
  probe('unhandled channel', () => const MethodChannel('repro/no_handler').invokeMethod<void>('x'));
  probe('SystemChrome.setPreferredOrientations',
      () => SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]));
  probe('SystemChrome.setEnabledSystemUIMode',
      () => SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge));
  probe('HapticFeedback.lightImpact', HapticFeedback.lightImpact);
  probe('Clipboard.getData', () => Clipboard.getData(Clipboard.kTextPlain));
  runApp(const Probe());
}

class Probe extends StatefulWidget {
  const Probe({super.key});

  @override
  State<Probe> createState() => _ProbeState();
}

class _ProbeState extends State<Probe> with WidgetsBindingObserver {
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    log('lifecycle: $state');
    if (state == AppLifecycleState.resumed) {
      probe('SystemChrome.setPreferredOrientations after resume',
          () => SystemChrome.setPreferredOrientations([DeviceOrientation.portraitUp]));
    }
  }

  @override
  Widget build(BuildContext context) =>
      const Directionality(textDirection: TextDirection.ltr, child: Center(child: Text('repro')));
}
