**Why it matters:** we found this in a shipping-candidate app, where a finger drawing was saved as a picture of unrelated on-screen art. Our workaround reads twice and checks the result against the strokes. Related, but different: #196265 (macOS, AMD, always zeros).

<details><summary>Code sample</summary>

```dart
import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

void main() => runApp(const MaterialApp(home: Stress()));

class Stress extends StatefulWidget {
  const Stress({super.key});
  @override
  State<Stress> createState() => _StressState();
}

class _StressState extends State<Stress> with SingleTickerProviderStateMixin {
  late final AnimationController _spin = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 2),
  )..repeat();
  final Map<String, int> _runs = {'single': 0, 'double': 0};
  final Map<String, int> _bad = {'single': 0, 'double': 0};
  final List<String> _examples = [];
  bool _done = false;
  static const int perMode = 1500;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _run());
  }

  @override
  void dispose() {
    _spin.dispose();
    super.dispose();
  }

  Future<void> _run() async {
    final random = math.Random(7);
    for (var i = 0; i < perMode * 2; i++) {
      final mode = i.isEven ? 'single' : 'double';
      final w = 500 + random.nextInt(600);
      final h = 500 + random.nextInt(600);
      final colour = HSVColor.fromAHSV(1, (i * 37) % 360, 0.9, 0.85).toColor();
      final bad = await _round(w, h, colour, mode == 'double');
      _runs[mode] = _runs[mode]! + 1;
      if (bad != null) {
        _bad[mode] = _bad[mode]! + 1;
        if (_examples.length < 8) _examples.add('$mode #$i ${w}x$h: $bad');
        debugPrint('STRESS BAD $mode #$i ${w}x$h: $bad');
      }
      // Every few rounds let a frame of the busy tiles through.
      if (i % 4 == 0) await WidgetsBinding.instance.endOfFrame;
      if (i % 50 == 0 && mounted) setState(() {});
    }
    debugPrint(
      'STRESS DONE single ${_bad['single']}/${_runs['single']} '
      'double ${_bad['double']}/${_runs['double']}',
    );
    if (mounted) setState(() => _done = true);
  }

  /// Null when the read is the picture, else what was wrong.
  Future<String?> _round(int w, int h, Color colour, bool twice) async {
    final recorder = ui.PictureRecorder();
    final canvas = Canvas(recorder);
    final line = math.min(w, h) * 0.06;
    final paint = Paint()
      ..color = colour
      ..style = PaintingStyle.stroke
      ..strokeWidth = line
      ..strokeCap = StrokeCap.round;
    final path = Path()
      ..moveTo(w * 0.2, h * 0.2)
      ..quadraticBezierTo(w * 0.5, h * 0.9, w * 0.8, h * 0.2)
      ..moveTo(w * 0.2, h * 0.5)
      ..lineTo(w * 0.8, h * 0.5);
    canvas.drawPath(path, paint);
    canvas.drawCircle(Offset(w * 0.5, h * 0.25), line, Paint()..color = colour);
    final picture = recorder.endRecording();
    final image = await picture.toImage(w, h);
    picture.dispose();
    if (twice) await image.toByteData();
    final data = await image.toByteData(
      format: ui.ImageByteFormat.rawStraightRgba,
    );
    image.dispose();
    if (data == null) return 'null data';
    final want = [
      (colour.r * 255).round(),
      (colour.g * 255).round(),
      (colour.b * 255).round(),
    ];
    String? check(double fx, double fy, {required bool ink}) {
      final x = (w * fx).floor(), y = (h * fy).floor();
      final at = (y * w + x) * 4;
      final px = [
        data.getUint8(at),
        data.getUint8(at + 1),
        data.getUint8(at + 2),
        data.getUint8(at + 3),
      ];
      if (ink) {
        final ok =
            px[3] > 240 &&
            (px[0] - want[0]).abs() <= 4 &&
            (px[1] - want[1]).abs() <= 4 &&
            (px[2] - want[2]).abs() <= 4;
        return ok ? null : 'ink at $fx,$fy is $px, want $want';
      }
      return px[3] < 8 ? null : 'clear at $fx,$fy is $px';
    }

    return check(0.5, 0.5, ink: true) ??
        check(0.3, 0.5, ink: true) ??
        check(0.7, 0.5, ink: true) ??
        check(0.5, 0.25, ink: true) ??
        check(0.05, 0.95, ink: false) ??
        check(0.95, 0.05, ink: false) ??
        check(0.5, 0.97, ink: false);
  }

  @override
  Widget build(BuildContext context) {
    final text = [
      _done ? 'DONE' : 'running…',
      'single read: ${_bad['single']} bad of ${_runs['single']}',
      'double read: ${_bad['double']} bad of ${_runs['double']}',
      ..._examples,
    ].join('\n');
    return Scaffold(
      body: Stack(
        fit: StackFit.expand,
        children: [
          CustomPaint(painter: _Tiles(_spin)),
          Center(
            child: Container(
              color: Colors.white,
              padding: const EdgeInsets.all(12),
              child: Text(text, style: const TextStyle(fontSize: 16)),
            ),
          ),
        ],
      ),
    );
  }
}

/// Busy 32 px tiles that move every frame, so GPU memory holds other art.
class _Tiles extends CustomPainter {
  _Tiles(this.t) : super(repaint: t);
  final Animation<double> t;
  @override
  void paint(Canvas canvas, Size size) {
    final shift = t.value * 64;
    for (var y = -64.0; y < size.height; y += 32) {
      for (var x = -64.0; x < size.width; x += 32) {
        final k = ((x + y) / 32).round();
        canvas.drawRect(
          Rect.fromLTWH(x + shift, y, 32, 32),
          Paint()
            ..color = HSVColor.fromAHSV(1, (k * 23 + t.value * 360) % 360, 0.5,
                    0.9)
                .toColor(),
        );
      }
    }
  }

  @override
  bool shouldRepaint(covariant _Tiles oldDelegate) => false;
}
```

