  var rasterMicros = 0;
  WidgetsFlutterBinding.ensureInitialized().addTimingsCallback((timings) {
    for (final timing in timings) {
      frameCount++;
      buildMicros += timing.buildDuration.inMicroseconds;
      rasterMicros += timing.rasterDuration.inMicroseconds;
    }
    globalContext
      ..setProperty('flutterFrameCount'.toJS, frameCount.toJS)
      ..setProperty('flutterBuildMicros'.toJS, buildMicros.toJS)
      ..setProperty('flutterRasterMicros'.toJS, rasterMicros.toJS);
  });

  runApp(
    Directionality(
      textDirection: TextDirection.ltr,
      child: ColoredBox(
        color: const Color(0xFFFFFFFF),
        child: Stack(
          fit: StackFit.expand,
          children: [
            if (cardCount > 0) RepaintBoundary(child: _Cards(count: cardCount)),
            Center(
              child: RepaintBoundary(
                child: isIdle ? const _Square() : const _SpinningSquare(),
              ),
            ),
          ],
        ),
      ),
    ),
  );
}

