                      Color(0xFFE53935),
                      Color(0xFF1E88E5),
                      Color(0xFF1E88E5),
                      Color(0xFFFDD835),
                      Color(0xFFFDD835),
                    ],
                    stops: const [0, 0.33, 0.33, 0.66, 0.66, 1],
                  ),
                ),
                child: const SizedBox.expand(),
              );
            },
          ),
          BackdropGroup(
            child: Center(
              child: Wrap(
                spacing: 24,
                runSpacing: 24,
                children: [
                  for (var i = 0; i < 6; i++)
                    ClipRRect(
                      borderRadius: BorderRadius.circular(16),
                      child: BackdropFilter.grouped(
                        filter: _filter(i),
                        child: const SizedBox(width: 80, height: 80),
