  Future<BitmapDescriptor> _getMarkerIcon(
    PictureInfo pictureInfo, {
    Size size = const Size(44, 44),
    String? text,
  }) async {
    double devicePixelRatio =
        PlatformDispatcher.instance.views.first.devicePixelRatio;
    int width = (size.width * devicePixelRatio).toInt();
    int height = (size.height * devicePixelRatio).toInt();

    final scaleFactor = min(
      width / pictureInfo.size.width,
      height / pictureInfo.size.height,
    );

    final recorder = PictureRecorder();

    final canvas = Canvas(recorder)
      ..save()
      ..scale(scaleFactor)
      ..drawPicture(pictureInfo.picture)
      ..restore();

    if (text != null) {
      final textStyle = TextStyle(
        color: Colors.black,
        fontWeight: FontWeight.bold,
        fontSize: 12 * devicePixelRatio,
      );
      final textSpan = TextSpan(text: text, style: textStyle);
      final textPainter = TextPainter(
        text: textSpan,
        textDirection: TextDirection.ltr,
      );
      textPainter.layout(minWidth: 0, maxWidth: width.toDouble());
      final xCenter = (width - textPainter.width) / 2;
      final yCenter = (height - textPainter.height) / 3;
      final offset = Offset(xCenter, yCenter);
      textPainter.paint(canvas, offset);
      textPainter.dispose();
    }

    final rasterPicture = recorder.endRecording();

    final image = await rasterPicture.toImage(width, height);
    final bytes = (await image.toByteData(format: ImageByteFormat.png))!;

    image.dispose();
    rasterPicture.dispose();

    return BytesMapBitmap(
      bytes.buffer.asUint8List(),
      imagePixelRatio: devicePixelRatio,
    );
  }

  /// Calculate geodesic distance in km between two LatLng points using Haversine formula
  double _calculateDistance(LatLng point1, LatLng point2) {
    const double earthRadiusKm = 6371.0;

    final lat1Rad = _toRadians(point1.latitude);
    final lat2Rad = _toRadians(point2.latitude);
    final deltaLatRad = _toRadians(point2.latitude - point1.latitude);
    final deltaLngRad = _toRadians(point2.longitude - point1.longitude);

    final a =
        sin(deltaLatRad / 2) * sin(deltaLatRad / 2) +
        cos(lat1Rad) *
            cos(lat2Rad) *
            sin(deltaLngRad / 2) *
            sin(deltaLngRad / 2);
    final c = 2 * atan2(sqrt(a), sqrt(1 - a));

    return earthRadiusKm * c;
  }

  /// Convert degrees to radians
  double _toRadians(double degrees) {
    return degrees * pi / 180.0;
  }
}

