<details><summary>lib/main.dart</summary>

```dart
// Repro: Picture.toImage -> Image.toByteData(rawRgba) intermittently returns
// pixels the GPU hasn't finished rendering (fully transparent, or partly
// drawn) on Impeller/Vulkan while the GPU is busy. Every frame is filled
// completely opaque, so ANY pixel with alpha != 255 is a bad readback.
import 'dart:async';
import 'dart:math';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';

void main() => runApp(const MaterialApp(home: ReproPage()));

class ReproPage extends StatefulWidget {
  const ReproPage({super.key});

  @override
  State<ReproPage> createState() => _ReproPageState();
}

class _ReproPageState extends State<ReproPage>
    with SingleTickerProviderStateMixin {
  static const int width = 1920;
  static const int height = 1080;
  static const int framesToRender = 750;
  static const int inFlight = 6;

  late final AnimationController _load =
      AnimationController(vsync: this, duration: const Duration(seconds: 1))
        ..repeat();
  int _done = 0;
  int _fullyTransparent = 0;
  int _partlyDrawn = 0;
  int _errors = 0;
  bool _running = false;

  @override
  void initState() {
    super.initState();
    // start once the first frame is up, so the onscreen load is running
    WidgetsBinding.instance.addPostFrameCallback((_) {
      Future<void>.delayed(const Duration(seconds: 2), _run);
    });
  }

  // like a per-frame 3D render: fresh RGBA pixels uploaded every frame
  Future<ui.Image> _upload(int frame) {
    const int bw = 900, bh = 1080;
    final Uint8List px = Uint8List(bw * bh * 4);
    final int v = (frame * 37) & 0xFF;
    for (int i = 0; i < px.length; i += 4) {
      px[i] = v; px[i + 1] = 255 - v; px[i + 2] = (i >> 10) & 0xFF; px[i + 3] = 255;
    }
    final Completer<ui.Image> c = Completer<ui.Image>();
    ui.decodeImageFromPixels(px, bw, bh, ui.PixelFormat.rgba8888, c.complete);
    return c.future;
  }

  ui.Picture _record(int frame, ui.Image upload) {
    final ui.PictureRecorder recorder = ui.PictureRecorder();
    final Canvas canvas = Canvas(recorder);
    // opaque everywhere
    canvas.drawRect(const Rect.fromLTWH(0, 0, width + 0.0, height + 0.0),
        Paint()..color = const Color(0xFF203040));
    final Random r = Random(frame);
    for (int i = 0; i < 400; i++) {
      canvas.drawCircle(
          Offset(r.nextDouble() * width, r.nextDouble() * height),
          10 + r.nextDouble() * 60,
          Paint()..color = Color(0xFF000000 | r.nextInt(0xFFFFFF)));
    }
    final ui.ParagraphBuilder pb = ui.ParagraphBuilder(ui.ParagraphStyle(fontSize: 64))
      ..pushStyle(ui.TextStyle(color: const Color(0xFFFFFFFF)))
      ..addText('frame $frame');
    final ui.Paragraph p = pb.build()..layout(const ui.ParagraphConstraints(width: 800));
    canvas.drawParagraph(p, const Offset(40, 40));
    canvas.drawImage(upload, const Offset(900, 0), Paint());
    return recorder.endRecording();
  }

  Future<void> _one(int frame) async {
    final ui.Image upload = await _upload(frame);
    ui.Picture? picture;
    ui.Image? image;
    try {
      picture = _record(frame, upload);
      image = await picture.toImage(width, height);
      final ByteData? bd = await image.toByteData(format: ui.ImageByteFormat.rawRgba);
      if (bd == null) {
        _errors++;
        return;
      }
      final Uint8List px = bd.buffer.asUint8List();
      int clear = 0; // alpha == 0
      int notOpaque = 0; // alpha != 255
      for (int i = 3; i < px.length; i += 4) {
        if (px[i] != 255) {
          notOpaque++;
          if (px[i] == 0) clear++;
        }
      }
      // one pixel inside the uploaded image must hold THIS frame's colour
      const int sx = 900 + 10, sy = 500;
      final int o = (sy * width + sx) * 4;
      final int v = (frame * 37) & 0xFF;
      final bool uploadOk = px[o] == v && px[o + 1] == 255 - v;
      if (clear == width * height) {
        _fullyTransparent++;
      } else if (notOpaque > 0 || !uploadOk) {
        _partlyDrawn++;
      }
    } catch (e) {
      _errors++;
      debugPrint('READBACK_REPRO frame $frame failed: $e');
    } finally {
      image?.dispose();
      picture?.dispose();
      upload.dispose();
    }
  }

  Future<void> _run() async {
    if (!mounted) return;
    setState(() {
      _running = true;
      _done = _fullyTransparent = _partlyDrawn = _errors = 0;
    });
    final List<Future<void>> pending = <Future<void>>[];
    for (int f = 0; f < framesToRender; f++) {
      late final Future<void> fut;
      fut = _one(f).whenComplete(() {
        pending.remove(fut);
        if (mounted) setState(() => _done++);
      });
      pending.add(fut);
      if (pending.length >= inFlight) await pending.first;
    }
    await Future.wait(List<Future<void>>.of(pending));
    debugPrint('READBACK_REPRO: $framesToRender frames, '
        'fully transparent: $_fullyTransparent, partly drawn: $_partlyDrawn, '
        'errors: $_errors');
    if (mounted) setState(() => _running = false);
  }

  @override
  void dispose() {
    _load.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(children: <Widget>[
        // onscreen GPU load running at the same time as the readbacks
        Positioned.fill(
          child: AnimatedBuilder(
            animation: _load,
            builder: (_, _) => ImageFiltered(
              imageFilter: ui.ImageFilter.blur(sigmaX: 20, sigmaY: 20),
              child: CustomPaint(painter: _LoadPainter(_load.value)),
            ),
          ),
        ),
        Center(
          child: Container(
            color: Colors.white,
            padding: const EdgeInsets.all(16),
            child: Column(mainAxisSize: MainAxisSize.min, children: <Widget>[
              Text('$_done / $framesToRender read back'),
              Text('fully transparent: $_fullyTransparent'),
              Text('partly drawn: $_partlyDrawn'),
              Text('errors: $_errors'),
              ElevatedButton(
                  onPressed: _running ? null : _run, child: const Text('Run')),
            ]),
          ),
        ),
      ]),
    );
  }
}

class _LoadPainter extends CustomPainter {
  _LoadPainter(this.t);
  final double t;

  @override
  void paint(Canvas canvas, Size size) {
    final Random r = Random(7);
    for (int i = 0; i < 2000; i++) {
      final double a = t * 2 * pi + i;
      canvas.drawCircle(
          Offset(size.width * (0.5 + 0.45 * sin(a * 1.3 + r.nextDouble())),
              size.height * (0.5 + 0.45 * cos(a * 0.7 + r.nextDouble()))),
          20,
          Paint()..color = Color(0x40000000 | r.nextInt(0xFFFFFF)));
    }
  }

  @override
  bool shouldRepaint(_LoadPainter old) => old.t != t;
}
