```kotlin
package com.example.repro_app

import android.opengl.EGL14
import android.opengl.EGLConfig
import android.opengl.GLES20
import android.os.Bundle
import android.util.Log
import io.flutter.embedding.android.FlutterActivity
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * Starts a second GPU user in this process: a thread with its own GLES
 * context rendering a heavy fragment shader into a 1920x1080 pbuffer in a
 * loop (stands in for an offscreen Filament render / Media3 Transformer
 * encode running alongside Flutter's offscreen readbacks).
 */
class MainActivity : FlutterActivity() {
    @Volatile private var running = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Thread(::glLoad, "gl-load").start()
    }

    override fun onDestroy() {
        running = false
        super.onDestroy()
    }

    /** The load is missing: say so loudly, since a silent no-op hides the bug. */
    private fun fail(what: String) {
        Log.e("READBACK_REPRO", "gl load thread NOT running: $what")
    }

    private fun glLoad() {
        val w = 1920
        val h = 1080
        val display = EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY)
        val version = IntArray(2)
        EGL14.eglInitialize(display, version, 0, version, 1)
        val configs = arrayOfNulls<EGLConfig>(1)
        val count = IntArray(1)
        EGL14.eglChooseConfig(display, intArrayOf(
            EGL14.EGL_RENDERABLE_TYPE, 4 /* EGL_OPENGL_ES2_BIT */,
            EGL14.EGL_SURFACE_TYPE, EGL14.EGL_PBUFFER_BIT,
            EGL14.EGL_RED_SIZE, 8, EGL14.EGL_GREEN_SIZE, 8, EGL14.EGL_BLUE_SIZE, 8,
            EGL14.EGL_ALPHA_SIZE, 8, EGL14.EGL_NONE), 0, configs, 0, 1, count, 0)
        if (count[0] == 0) return fail("no RGBA8888 pbuffer EGL config")
        val context = EGL14.eglCreateContext(display, configs[0], EGL14.EGL_NO_CONTEXT,
            intArrayOf(EGL14.EGL_CONTEXT_CLIENT_VERSION, 2, EGL14.EGL_NONE), 0)
        if (context == EGL14.EGL_NO_CONTEXT) return fail("eglCreateContext")
        val surface = EGL14.eglCreatePbufferSurface(display, configs[0],
            intArrayOf(EGL14.EGL_WIDTH, w, EGL14.EGL_HEIGHT, h, EGL14.EGL_NONE), 0)
        if (surface == EGL14.EGL_NO_SURFACE) return fail("eglCreatePbufferSurface")
        if (!EGL14.eglMakeCurrent(display, surface, surface, context)) return fail("eglMakeCurrent")

        val vs = """
            attribute vec2 p; varying vec2 uv;
            void main() { uv = p * 0.5 + 0.5; gl_Position = vec4(p, 0.0, 1.0); }
        """.trimIndent()
        // deliberately expensive per pixel
        val fs = """
            precision highp float; varying vec2 uv; uniform float t;
            void main() {
              vec3 c = vec3(0.0);
              for (int i = 0; i < 64; i++) {
                float f = float(i);
                c += 0.5 + 0.5 * sin(vec3(uv * (f + 3.0), t + f) * 1.7);
              }
              gl_FragColor = vec4(c / 64.0, 1.0);
            }
        """.trimIndent()
        val program = GLES20.glCreateProgram()
        for ((type, src) in listOf(GLES20.GL_VERTEX_SHADER to vs, GLES20.GL_FRAGMENT_SHADER to fs)) {
            val s = GLES20.glCreateShader(type)
            GLES20.glShaderSource(s, src)
            GLES20.glCompileShader(s)
            val ok = IntArray(1)
            GLES20.glGetShaderiv(s, GLES20.GL_COMPILE_STATUS, ok, 0)
            if (ok[0] == 0) return fail("shader compile: ${GLES20.glGetShaderInfoLog(s)}")
            GLES20.glAttachShader(program, s)
        }
        GLES20.glLinkProgram(program)
        val linked = IntArray(1)
        GLES20.glGetProgramiv(program, GLES20.GL_LINK_STATUS, linked, 0)
        if (linked[0] == 0) return fail("program link: ${GLES20.glGetProgramInfoLog(program)}")
        GLES20.glUseProgram(program)
        val quad = ByteBuffer.allocateDirect(8 * 4).order(ByteOrder.nativeOrder()).asFloatBuffer()
            .put(floatArrayOf(-1f, -1f, 1f, -1f, -1f, 1f, 1f, 1f)).also { it.position(0) }
        val loc = GLES20.glGetAttribLocation(program, "p")
        GLES20.glEnableVertexAttribArray(loc)
        GLES20.glVertexAttribPointer(loc, 2, GLES20.GL_FLOAT, false, 0, quad)
        val tLoc = GLES20.glGetUniformLocation(program, "t")
        GLES20.glViewport(0, 0, w, h)

        Log.i("READBACK_REPRO", "gl load thread running")
        var frames = 0
        val start = System.nanoTime()
        while (running) {
            GLES20.glUniform1f(tLoc, frames * 0.016f)
            GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP, 0, 4)
            GLES20.glFinish()
            frames++
            if (frames % 300 == 0) {
                val s = (System.nanoTime() - start) / 1e9
                Log.i("READBACK_REPRO", "gl load: $frames frames, ${"%.1f".format(frames / s)} fps")
            }
        }
        EGL14.eglMakeCurrent(display, EGL14.EGL_NO_SURFACE, EGL14.EGL_NO_SURFACE, EGL14.EGL_NO_CONTEXT)
        EGL14.eglDestroySurface(display, surface)
        EGL14.eglDestroyContext(display, context)
    }
}
