  final DiagnosticPropertiesBuilder builder = DiagnosticPropertiesBuilder();
  picture.debugFillProperties(builder);
  for (final DiagnosticsNode property in builder.properties) {
    if (!property.isFiltered(DiagnosticLevel.info)) {
      print(property);  // Prints "clipBehavior: hardEdge".
    }
  }
}
