1. Command buffer 1: a render pass into texture A (512 × 512, `r8g8b8a8UNormInt`, device private) whose fragment shader spends some time and writes opaque red. Submit.
2. Command buffer 2: a render pass into texture B whose fragment shader copies A. Submit.
3. Right away, without waiting for the completion callback, read B back with `B.asImage().toByteData(format: ImageByteFormat.rawRgba)`.

The app below does this 40 times, alternating a read right away with a read after the second submission's completion callback, and prints the center pixel counts. The manifest enables Flutter GPU, sets `io.flutter.embedding.android.ImpellerBackend` to `vulkan` (this device is otherwise on the GLES list) and turns on `EnableVulkanValidation`.

<details><summary>lib/main.dart</summary>

```dart
import 'dart:async';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/widgets.dart';
import 'package:flutter_gpu/gpu.dart' as gpu;
import 'package:vector_math/vector_math.dart' as vm;

void main() {
  runApp(const Center(child: Text('repro', textDirection: TextDirection.ltr)));
  WidgetsBinding.instance.addPostFrameCallback((_) => run());
}

final layout = gpu.VertexLayout(
  buffers: [
    gpu.VertexBuffer(
      strideInBytes: 8,
      attributes: [gpu.VertexAttribute(name: 'position', format: gpu.VertexFormat.float32x2)],
    ),
  ],
);

gpu.Texture target(int size) =>
    gpu.gpuContext.createTexture(gpu.StorageMode.devicePrivate, size, size, format: gpu.PixelFormat.r8g8b8a8UNormInt);

// A pass that clears [texture] to blue and draws [fragment] over all of it, sampling [source] if given.
gpu.CommandBuffer pass(gpu.ShaderLibrary library, gpu.Texture texture, String fragment, [gpu.Texture? source]) {
  final context = gpu.gpuContext;
  final shader = library[fragment]!;
  final commands = context.createCommandBuffer();
  final pass = commands.createRenderPass(
    gpu.RenderTarget.singleColor(gpu.ColorAttachment(texture: texture, clearValue: vm.Vector4(0, 0, 1, 1))),
  );
  pass
    ..bindPipeline(context.createRenderPipeline(library['QuadVertex']!, shader, vertexLayout: layout))
    ..bindVertexBuffer(
      gpu.BufferView(
        context.createDeviceBufferWithCopy(Float32List.fromList([-1, -1, 3, -1, -1, 3]).buffer.asByteData()),
        offsetInBytes: 0,
        lengthInBytes: 24,
      ),
    );

  if (source != null) {
    pass.bindTexture(shader.getUniformSlot('source'), source);
  }

  pass.draw(3);
  return commands;
}

// Pass 1 draws red into `first`; pass 2, a separate submission, copies `first` into `second`, which is read back
// right after submitting (even trials) or after the completion callback (odd trials).
Future<void> run() async {
  const size = 512;
  final library = (await gpu.ShaderLibrary.fromAsset('build/shaderbundles/repro.shaderbundle'))!;
  final counts = <String, Map<String, int>>{'right away': {}, 'after completion': {}};

  for (var i = 0; i < 40; i++) {
    final first = target(size);
    final second = target(size);
    final done = Completer<void>();
    pass(library, first, 'HeavyFragment').submit();
    pass(library, second, 'CopyFragment', first).submit(completionCallback: (_) => done.complete());

    if (i.isOdd) {
      await done.future;
    }

    final bytes = (await second.asImage().toByteData(format: ui.ImageByteFormat.rawRgba))!;
    final center = (size ~/ 2 * size + size ~/ 2) * 4;
    final pixel = [for (var c = 0; c < 4; c++) bytes.getUint8(center + c)];
    final counted = counts[i.isOdd ? 'after completion' : 'right away']!;
    counted['$pixel'] = (counted['$pixel'] ?? 0) + 1;
    await done.future;
  }

  print('REPRO $counts');
  print('REPRO done');
}
```

