class _ProximityReproState extends State<ProximityRepro>
    with SingleTickerProviderStateMixin {
  static const _channel = MethodChannel('proximity_repro');

  late final _animation = AnimationController(
    vsync: this,
    duration: const Duration(seconds: 2),
  );
  Timer? _timeout;
  bool _running = false;
  bool _changing = false;
  String _status = 'Start the test, then cover the proximity sensor.';

  Future<void> _toggle() async {
    if (_changing) return;
    setState(() => _changing = true);
    try {
      if (_running) {
        await _channel.invokeMethod<void>('stop');
        _timeout?.cancel();
        _animation.stop();
        if (mounted) {
          setState(() {
            _running = false;
            _status = 'Test stopped.';
          });
        }
      } else {
        final supported = await _channel.invokeMethod<bool>('start') ?? false;
        if (!mounted) return;
        if (supported) {
          _animation.repeat();
          _timeout = Timer(
            const Duration(minutes: 2),
            () => unawaited(_toggle()),
          );
        }
        setState(() {
          _running = supported;
          _status = supported
              ? 'Cover the sensor for 40 seconds, then uncover it.'
              : 'Proximity screen-off wake locks are unavailable on this device.';
        });
      }
    } on PlatformException catch (error) {
      if (mounted) setState(() => _status = 'Android error: ${error.code}');
    } finally {
      if (mounted) setState(() => _changing = false);
    }
  }

  @override
  void dispose() {
    _timeout?.cancel();
    _animation.dispose();
    super.dispose();
