```kotlin
package dev.example.proximity_repro

import android.os.PowerManager
import android.util.Log
import android.view.WindowManager
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {
    private var proximityLock: PowerManager.WakeLock? = null

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "proximity_repro")
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "start" -> result.success(startProximityTest())
                    "stop" -> {
                        stopProximityTest()
                        result.success(null)
                    }
                    else -> result.notImplemented()
                }
            }
    }

    @Suppress("DEPRECATION")
    private fun startProximityTest(): Boolean {
        if (proximityLock?.isHeld == true) return true
        val power = getSystemService(PowerManager::class.java)
        val level = PowerManager.PROXIMITY_SCREEN_OFF_WAKE_LOCK
        if (!power.isWakeLockLevelSupported(level)) return false

        proximityLock = power.newWakeLock(level, "$packageName:proximity").apply {
            setReferenceCounted(false)
            acquire(120_000)
        }
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        Log.i("ProximityRepro", "Wake lock acquired (120 second cap)")
        return true
    }

    private fun stopProximityTest() {
        proximityLock?.let { lock ->
            if (lock.isHeld) lock.release()
        }
        proximityLock = null
        window.clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        Log.i("ProximityRepro", "Test stopped")
    }

    override fun onDestroy() {
        stopProximityTest()
        super.onDestroy()
    }
}
```

