// Repro runner: the main window renders continuously; additional top-level
// windows, each with its own FlutterViewController (a second engine sharing
// the process-wide EGLDisplay), are created on the platform thread, the way
// desktop_multi_window 0.3.0 does it. Engines are never destroyed.
//
// Flags (also visible to Dart): --count=N engines to create, --trigger=timer
// (every --interval ms) or --trigger=frames (on every --every'th main-window
// frame), --linger=ms after the last one, --log=path.
#include <flutter/binary_messenger.h>
#include <flutter/dart_project.h>
#include <flutter/flutter_view_controller.h>
#include <share.h>
#include <windows.h>

#include <cstdarg>
#include <cstdio>
#include <cstring>
#include <memory>
#include <string>
#include <vector>

#include "flutter_window.h"
#include "utils.h"

static int g_count = 30, g_interval = 500, g_every = 30, g_linger = 3000;
static bool g_frame_trigger = false;
static FILE* g_log = nullptr;
static ULONGLONG g_t0 = 0;
static long long g_frames = 0;
static std::vector<std::unique_ptr<FlutterWindow>> g_windows;

static void Log(const char* fmt, ...) {
  if (!g_log) return;
  fprintf(g_log, "%8llu ms frames=%lld ", GetTickCount64() - g_t0, g_frames);
  va_list ap;
  va_start(ap, fmt);
  vfprintf(g_log, fmt, ap);
  va_end(ap);
  fputc('\n', g_log);
  fflush(g_log);
}

// Exit without tearing engines down: teardown is a different race.
static void CALLBACK Finish(HWND, UINT, UINT_PTR, DWORD) {
  Log("SURVIVED engines=%zu", g_windows.size());
  fclose(g_log);
  ::TerminateProcess(::GetCurrentProcess(), 0);
}

static void CreateSecondary() {
  if (static_cast<int>(g_windows.size()) >= g_count) return;
  int id = static_cast<int>(g_windows.size()) + 1;
  flutter::DartProject project(L"data");
  project.set_dart_entrypoint_arguments({"secondary", std::to_string(id)});
  auto window = std::make_unique<FlutterWindow>(project);
  Log("engine %d create begin", id);
  bool ok = window->Create(L"secondary", Win32Window::Point(700 + 15 * (id % 20), 80 + 15 * (id % 20)),
                           Win32Window::Size(480, 320));
  Log("engine %d create end ok=%d", id, ok ? 1 : 0);
  g_windows.push_back(std::move(window));
  if (static_cast<int>(g_windows.size()) == g_count) ::SetTimer(nullptr, 0, g_linger, Finish);
}

static void CALLBACK OnTimer(HWND, UINT, UINT_PTR id, DWORD) {
  CreateSecondary();
  if (static_cast<int>(g_windows.size()) >= g_count) ::KillTimer(nullptr, id);
}

int APIENTRY wWinMain(_In_ HINSTANCE instance, _In_opt_ HINSTANCE prev,
                      _In_ wchar_t* command_line, _In_ int show_command) {
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
  g_t0 = GetTickCount64();

  std::vector<std::string> args = GetCommandLineArguments();
  std::wstring log_path;
  for (const std::string& a : args) {
    auto val = [&](const char* name) { return a.substr(strlen(name)); };
    if (a.rfind("--count=", 0) == 0) g_count = std::stoi(val("--count="));
    if (a.rfind("--interval=", 0) == 0) g_interval = std::stoi(val("--interval="));
    if (a.rfind("--every=", 0) == 0) g_every = std::stoi(val("--every="));
    if (a.rfind("--linger=", 0) == 0) g_linger = std::stoi(val("--linger="));
    if (a == "--trigger=frames") g_frame_trigger = true;
    if (a.rfind("--log=", 0) == 0) log_path = std::wstring(a.begin() + 6, a.end());
  }
  if (log_path.empty()) {
    wchar_t exe[MAX_PATH];
    ::GetModuleFileNameW(nullptr, exe, MAX_PATH);
    log_path = std::wstring(exe);
    log_path = log_path.substr(0, log_path.find_last_of(L'\\') + 1) + L"repro_log.txt";
  }
  g_log = _wfsopen(log_path.c_str(), L"w", _SH_DENYNO);
  Log("start pid=%lu count=%d trigger=%s interval=%d every=%d", ::GetCurrentProcessId(), g_count,
      g_frame_trigger ? "frames" : "timer", g_interval, g_every);

  flutter::DartProject project(L"data");
  project.set_dart_entrypoint_arguments(args);
  FlutterWindow window(project);
  if (!window.Create(L"angle_race_repro", Win32Window::Point(10, 10), Win32Window::Size(1280, 720))) {
    return EXIT_FAILURE;
  }
  window.SetQuitOnClose(true);

  window.controller()->engine()->messenger()->SetMessageHandler(
      "repro/frames", [](const uint8_t* msg, size_t size, flutter::BinaryReply reply) {
        if (size == 8) memcpy(&g_frames, msg, 8);
        if (g_frames % 300 == 0) Log("heartbeat");
        if (g_frame_trigger && g_frames >= 120 && g_frames % g_every == 0) CreateSecondary();
        reply(nullptr, 0);
      });
  if (!g_frame_trigger) ::SetTimer(nullptr, 0, g_interval, OnTimer);

  ::MSG msg;
  while (::GetMessage(&msg, nullptr, 0, 0)) {
    ::TranslateMessage(&msg);
    ::DispatchMessage(&msg);
  }
  ::CoUninitialize();
  return EXIT_SUCCESS;
}
