        if (kind >= 4) {
          final oval = Rect.fromLTWH(origin.dx, origin.dy + 10, 16, 5.5);
          canvas.drawOval(oval, Paint()..color = const Color(0xFF605020));
          canvas.drawOval(oval, stroke);
          continue;
        }
        final path = Path();
        for (var i = 0; i < arcCount; i++) {
          final ellipse = Rect.fromLTWH(
            origin.dx,
            origin.dy + i * arcSpacing,
            16,
            5.5,
          );
          if (kind < 2) {
            canvas.drawArc(ellipse, 0, 3.14159265, false, stroke);
          } else {
            path.addArc(ellipse, 0, 3.14159265);
          }
        }
        if (kind >= 2) canvas.drawPath(path, stroke);
      }
    }
  }

  @override
  bool shouldRepaint(ThinArcsPainter old) => false;
