import 'package:flutter/rendering.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget wheel({FixedExtentScrollController? controller, double opacity = 0.5}) {
  return Directionality(
    textDirection: TextDirection.ltr,
    child: ListWheelScrollView(
      controller: controller,
      overAndUnderCenterOpacity: opacity,
      itemExtent: 20,
      children: <Widget>[for (int i = 0; i < 20; i++) Container()],
    ),
  );
}

void main() {
  testWidgets('reuses the OpacityLayer when it repaints', (WidgetTester tester) async {
    final controller = FixedExtentScrollController();
    addTearDown(controller.dispose);
    await tester.pumpWidget(wheel(controller: controller));
    final OpacityLayer layer = tester.layers.whereType<OpacityLayer>().single;

    controller.jumpTo(50);
    await tester.pump();

    expect(tester.layers.whereType<OpacityLayer>().single, same(layer)); // Fails.
  });

  testWidgets('releases the OpacityLayer at opacity 1', (WidgetTester tester) async {
    await tester.pumpWidget(wheel());
    final OpacityLayer layer = tester.layers.whereType<OpacityLayer>().single;

    await tester.pumpWidget(wheel(opacity: 1));

    expect(tester.layers.whereType<OpacityLayer>(), isEmpty); // Passes.
    expect(layer.debugDisposed, isTrue); // Fails.
  });
}
