  State<Demo> createState() => _DemoState();
}

class _DemoState extends State<Demo> {
  double value = 0.5;
  @override
  Widget build(BuildContext context) => Scaffold(
        body: Center(
          child: Slider(
            value: value,
            label: 'Zoom',
            onChanged: (v) {
              debugPrint('onChanged $v');
              setState(() => value = v);
            },
